def find_chain(start, end):
    stack = [(start, [])]
    visited = set()
    while stack:
        current, path = stack.pop()
        if current == end:
            return path + [current]
        if current not in visited:
            visited.add(current)
            for next_char in get_next_chars(current):
                stack.append((next_char, path + [current]))
    return None

def get_next_chars(s):
    return [c for c in s if c not in 'abcdefghijklmnopqrstuvwxyz']

# Example usage:
# start, end = find_chain('a', 'z')
# print(end)  # Output: 'a', 'z'
